const ASSETS = ["./","chunks/browser-DYQWO4C2.js","chunks/chunk-5VEMRWQW.js","chunks/chunk-7VP2RNID.js","chunks/chunk-BIX5Q65Y.js","chunks/chunk-OPBDWSLH.js","chunks/chunk-PB4S2B7M.js","chunks/chunk-S6BMAXLK.js","chunks/chunk-U5ZB4QVA.js","chunks/chunk-VZEB4T5Y.js","chunks/chunk-YHB35L3X.js","chunks/clike-IPBPKYRK.js","chunks/css-PTV2WPKK.js","chunks/diff-7UJ2JNQW.js","chunks/dist-2N7A57HA.js","chunks/dist-7MP4SRZM.js","chunks/dist-DUBF32H7.js","chunks/dist-ECVZ36PJ.js","chunks/dist-P3WBE2CF.js","chunks/dist-VIBG5FRD.js","chunks/dist-WCTEYMEN.js","chunks/dist-YOCT6VPD.js","chunks/dockerfile-74HXQQ3L.js","chunks/emmet.es-IZMNQZDX.js","chunks/gitService-KUPMQSKV.js","chunks/go-BF6FJ6SI.js","chunks/lua-5VHOUJYM.js","chunks/marked.esm-CST3UKEQ.js","chunks/properties-2OMSV6II.js","chunks/ruby-XHQFHHDW.js","chunks/rust-AF5N33M4.js","chunks/shell-U674A2Q4.js","chunks/sql-VNHXXUV6.js","chunks/swift-66CUN4T3.js","chunks/toml-Y6PYX4D3.js","chunks/xml-KKDBUW2H.js","chunks/yaml-V62K2PD3.js","format-worker.js","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png","icons/icon.svg","index.html","main.js","manifest.webmanifest","run-worker.js","styles.css"];
const CACHE = `codeeditor-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(ASSETS)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('codeeditor-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // Always from the network: it's how the app learns that a newer build exists.
  if (url.pathname.endsWith('/version.json')) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (err) {
      if (req.mode === 'navigate') return (await cache.match('./')) || (await cache.match('index.html'));
      throw err;
    }
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skip-waiting') self.skipWaiting();
});
